import {
    AgentResponse,
    RequestParams,
    DataFrom,
    ListResponseData,
} from './misc';
import { makeCveLink } from './wordpress-utils';

export interface IUserDomain {
    domain: string;
    docroot?: string;
}

type WordpressDomainsResponse = AgentResponse<ListResponseData<IUserDomain>>;

interface IWordpressRulesListParams {
    offset?: number;
    domains?: string[];
    limit?: number;
}

interface IWordpressRuleInBackend {
    domains?: string[] | null;
    rule_id: string;
    is_global?: boolean | null;
    component?: string | null;
    versions?: string | null;
}

export class WordpressRule {
    domains: string[];
    rule_id: string;
    is_global: boolean;
    component: string;
    versions: string;
    domainsList: string;
    cveLink: string | null;

    constructor({rule_id, is_global, versions, component, domains}: IWordpressRuleInBackend) {
        this.rule_id = rule_id;
        this.is_global = is_global || false;
        this.component = component || '';
        this.versions = versions || '';
        this.domains = domains || [];
        this.cveLink = makeCveLink(rule_id);
        this.domainsList = this.domains.join(', ');
    }
}

type WordpressRulesAgentResponse = AgentResponse<ListResponseData<IWordpressRuleInBackend>>;

export class WordPressPluginAPI {
    static listSites(params =  {}) {
        return new RequestParams<DataFrom<WordpressDomainsResponse>>(['wordpress-plugin', 'list-sites'], params);
    }

    static listRules = (params: IWordpressRulesListParams) =>
        new RequestParams<DataFrom<WordpressRulesAgentResponse>>
        (['wordpress-plugin', 'rules', 'list-disabled'], params)

    static enableRule(rule: WordpressRule) {
        return new RequestParams(['wordpress-plugin', 'rules', 'enable'], {
            rule: rule.rule_id,
        });
    }

    static disableRule(params: { rule: string, domains?: string[] }) {
        return new RequestParams(['wordpress-plugin', 'rules',  'disable'], params);
    }
}
