import { Component } from '@angular/core';
import { MatDialogRef } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { ModalEntry } from 'app/utils/modals/entry';

export interface DowngradeDialogResult {
    action: 'downgrade' | 'upgrade' | 'cancel';
}

@Component({
    selector: 'i360-downgrade-dialog',
    template: `
        <i360-modal-content
            [showCancel]="false"
            [showConfirm]="false"
            [cancelText]="'utils.modals.content.cancel'">
            <ng-container modal-title>
                {{ 'license.downgradeTitle' | translate }}
            </ng-container>
            <ng-container modal-body>
                <div class="feature-modal-body">
                    <p>
                        {{ 'license.noValidLicenseForImunify360Installation' | translate }}
                    </p>
                </div>
            </ng-container>
            <ng-container modal-actions>
                <button
                    class="confirm-button btn-link mat-focus-indicator mat-button mat-button-base mat-primary uppercase"
                    (click)="downgrade()"
                    type="button"
                    color="primary">
                    {{ 'license.downgradeToFreeAV' | translate }}
                </button>
                <button
                    class="confirm-button btn-link mat-focus-indicator mat-button mat-button-base mat-primary uppercase"
                    (click)="upgrade()"
                    color="primary">
                    {{ 'license.upgrade' | translate }}
                </button>
            </ng-container>
        </i360-modal-content>
    `,
    styles: [`

        .confirm-button {
            padding: 0 16px;
        }
        .confirm-button:hover {
             background-color: #f6fdfa !important;
        }

    `],
})
export class DowngradeDialogComponent extends ModalEntry<void, DowngradeDialogResult> {
    constructor(
        private dialogRef: MatDialogRef<DowngradeDialogComponent>,
        private router: Router,
    ) {
        super();
    }

    downgrade() {
        this.dialogRef.close({action: 'downgrade'});
    }

    upgrade() {
        this.dialogRef.close({action: 'upgrade'});
        this.router.navigate(['/', 'AV', 'admin', 'upgrade']);
    }
}
