import {
    AgentResponse,
    DataFrom,
    ListResponseData,
    RequestParams, ResponseDataExceptItems,
} from './misc';

export enum VulnerabilitiesFileStatus {
    patched = 'patched',
    vulnerable = 'vulnerable',
    vulnerable_patch_reverted = 'vulnerable_patch_reverted',
    patch_in_progress = 'patch_in_progress',
    revert_in_progress = 'revert_in_progress',
}


interface Vulnerability {
  cve_id: string;
  vulnerability_type: string; // e.g., "XSS"
  vulnerability_description: string;
}

interface VulnerabilitiesItemInBackend {
  id: number;
  app_name: string; // e.g., "WordPress", "WordPress plugin 'FormsPRO++ ...'"
  username: string;
  file_path: string;
  subscribed?: boolean | null;
  imunify_patch_user_id?: string | null;
  purchase_url?: string | null;
  status: VulnerabilitiesFileStatus;
  vulnerabilities: Vulnerability[];
}

export class VulnerabilitiesApi {

    static list = (params = {}) =>
        new RequestParams<DataFrom<VulnerabilitiesListAgentResponse>>
        (['vulnerabilities', 'file', 'list'], params)

    static applyPatch(
        {items}: {items: string[]},
    ) {
        return new RequestParams<ResponseDataExceptItems>(
            ['vulnerabilities', 'file', 'patch'], {
             paths: items,
        });
    }

    static revertPatch(
        {items}: {items: string[]},
    ) {
        return new RequestParams<ResponseDataExceptItems>(
            ['vulnerabilities', 'file', 'revert'], {
            paths: items,
        });
    }
}

export class VulnerabilitiesItem {
    public canExpand = true;
    public appName: string;
    public id: number;
    public userName: string;
    public filePath: string;
    public imunify_patch_user_id: string;
    public subscribed: boolean;
    public purchaseUrl: string | null;
    public status: VulnerabilitiesFileStatus;
    public vulnerabilities: Vulnerability[];
    constructor(data: VulnerabilitiesItemInBackend) {
        this.id = data.id;
        this.appName = data.app_name;
        this.userName = data.username;
        this.status = data.status;
        if (data?.imunify_patch_user_id) {
            this.imunify_patch_user_id = data.imunify_patch_user_id;
        }
        if (data?.subscribed) {
            this.subscribed = data.subscribed;
        }
        this.purchaseUrl = data?.purchase_url ?? null;
        this.filePath = data.file_path;
        this.vulnerabilities = data.vulnerabilities;
    }
}


type VulnerabilitiesListAgentResponse = AgentResponse<ListResponseData<VulnerabilitiesItemInBackend>>;
