import {
    AfterViewInit,
    Component,
    ContentChildren,
    ElementRef,
    HostBinding,
    OnDestroy,
    QueryList,
    TemplateRef,
    ViewChild,
    ViewEncapsulation,
    ChangeDetectorRef,
    NgZone,
} from '@angular/core';
import {
    Subject,
    combineLatest,
    interval,
    EMPTY,
    switchMap,
    takeUntil,
    observeOn,
    asyncScheduler,
} from 'rxjs';
import { ImunifyTemplateDirective } from 'app/utils/table/template.directive';
import { animate, transition, trigger } from '@angular/animations';
import { TranslateService } from '@ngx-translate/core';
import { MatMenuItem } from '@angular/material/menu';
import { I360Config } from 'app/utils/config/config';
import { RuleSet } from '@imunify360-api/settings';
import { AppState } from 'app/core/app.service';
import { Panel } from 'app/utils/panel';
import { LicenseState } from 'app/services/license-state';
import { LicenseService } from 'app/services/license';
import { AuthState } from 'app/services/auth-state';
import { AuthService, I360Role } from 'app/services/auth';
import { MyImunifyService } from 'app/services/my-imunify';
import { IMyImunifyState } from 'app/services/my-imunify-state';

export const updateTokenInterval = 150000;

const MOBILE_BREAKPOINT = 768;
const NAV_MAX_HEIGHT = 87;

@Component({
    selector: 'i360-navigation',
    templateUrl: './navigation.component.html',
    styleUrls: ['./navigation.component.scss'],
    encapsulation: ViewEncapsulation.None,
    animations: [
        trigger('navClosed', [
            transition(':leave', [animate(0)]),
            transition('* => *', [animate(600)]),
        ]),
    ],
})
export class NavigationComponent implements AfterViewInit, OnDestroy {
    @ViewChild('navWrapper', {static: true}) navWrapper: ElementRef;
    @ViewChild('logoContainer', {static: true}) logoContainer: ElementRef;

    @HostBinding('attr.role') readonly role = 'navigation';
    @ContentChildren(ImunifyTemplateDirective, {descendants: true})
    templates: QueryList<ImunifyTemplateDirective>;
    @HostBinding('class.i360-nav-closed') @HostBinding('@navClosed') closed: boolean = true;

    leftTemplates: Array<TemplateRef<any>> = [];
    rightTemplates: Array<TemplateRef<any>> = [];
    buttonTemplates: Array<TemplateRef<any>> = [];
    dropTemplates: Array<TemplateRef<any>> = [];
    copyOfDropTemplates: Array<TemplateRef<any>> = [];
    logoTemplate?: TemplateRef<any>;
    myImunifyState: IMyImunifyState;
    protection: string;
    isReady = false;

    private allMenuTemplates: Array<TemplateRef<any>> = [];
    private resizeObserver: ResizeObserver | null = null;
    private destroyed = new Subject<void>();
    private lastNavWidth = 0;

    constructor(
        public elementRef: ElementRef,
        private cdr: ChangeDetectorRef,
        private ngZone: NgZone,
        private translateService: TranslateService,
        public appState: AppState,
        public authState: AuthState,
        public config: I360Config,
        public licenseState: LicenseState,
        public licenseService: LicenseService,
        public panel: Panel,
        public authService: AuthService,
        private myImunifyService: MyImunifyService,
    ) {
        this.listenMyImunifyState();
        this.checkLowResourceMode();
    }

    ngAfterViewInit() {
        this.collectTemplates();
        this.leftTemplates = [...this.allMenuTemplates];
        this.cdr.detectChanges();

        this.normalize();
        this.isReady = true;
        this.cdr.detectChanges();

        this.setupResizeObserver();

        this.templates.changes.pipe(
            observeOn(asyncScheduler),
            takeUntil(this.destroyed),
        ).subscribe(() => this.rebuild());

        this.translateService.onLangChange.pipe(takeUntil(this.destroyed)).subscribe(() => {
            this.rebuild();
        });

        if (this.panel.isNoPanel) {
            this.autoUpdateToken();
        }
    }

    ngOnDestroy() {
        this.destroyed.next();
        this.resizeObserver?.disconnect();
    }

    rebuild(): void {
        this.isReady = false;
        this.collectTemplates();
        this.leftTemplates = [...this.allMenuTemplates];
        this.dropTemplates = [];
        this.cdr.detectChanges();

        this.normalize();
        this.isReady = true;
        this.cdr.detectChanges();
    }

    clickMenuItem(matMenuItem: MatMenuItem) {
        matMenuItem['_elementRef'].nativeElement.querySelector('a')!.click();
    }

    private collectTemplates(): void {
        this.allMenuTemplates = [];
        this.rightTemplates = [];
        this.buttonTemplates = [];
        this.logoTemplate = undefined;

        this.templates.forEach(template => {
            switch (template.name) {
                case 'button':
                    this.buttonTemplates.push(template.template);
                    break;
                case 'right':
                    this.rightTemplates.push(template.template);
                    break;
                case 'logo':
                    this.logoTemplate = template.template;
                    break;
                default:
                    this.allMenuTemplates.push(template.template);
                    break;
            }
        });
    }

    private setupResizeObserver(): void {
        this.ngZone.runOutsideAngular(() => {
            this.resizeObserver = new ResizeObserver(() => {
                const newWidth = this.navWrapper.nativeElement.offsetWidth;
                if (newWidth !== this.lastNavWidth) {
                    this.lastNavWidth = newWidth;
                    this.ngZone.run(() => {
                        this.normalize();
                        this.cdr.detectChanges();
                    });
                }
            });
            this.resizeObserver.observe(this.navWrapper.nativeElement);
        });
    }

    private isNavHeightOk(): boolean {
        const navRect = this.navWrapper.nativeElement.getBoundingClientRect();
        return navRect.height <= NAV_MAX_HEIGHT;
    }

    private moveToDropdown(): boolean {
        if (this.leftTemplates.length === 0) return false;
        const item = this.leftTemplates.pop();
        if (item) {
            this.dropTemplates.unshift(item);
            return true;
        }
        return false;
    }

    private moveFromDropdown(): boolean {
        if (this.dropTemplates.length === 0) return false;
        const item = this.dropTemplates.shift();
        if (item) {
            this.leftTemplates.push(item);
            return true;
        }
        return false;
    }

    private normalize(): void {
        if (window.innerWidth < MOBILE_BREAKPOINT) {
            this.leftTemplates = [...this.allMenuTemplates];
            this.dropTemplates = [];
            this.copyOfDropTemplates = [];
            return;
        }

        while (this.dropTemplates.length > 0) {
            this.moveFromDropdown();
            this.cdr.detectChanges();

            if (!this.isNavHeightOk()) {
                this.moveToDropdown();
                this.cdr.detectChanges();
                break;
            }
        }

        let maxIterations = 20;
        while (!this.isNavHeightOk() && maxIterations-- > 0) {
            if (!this.moveToDropdown()) break;
            this.cdr.detectChanges();
        }

        this.copyOfDropTemplates = [...this.dropTemplates];
        this.cdr.detectChanges();
    }

    autoUpdateToken() {
        combineLatest([
            this.authState.username,
            this.authState.role,
            interval(updateTokenInterval),
        ]).pipe(
            switchMap(([username, role, _]: [string, I360Role, number]) => {
                return !!username && role === I360Role.admin
                    ? this.licenseService.getToken({username}) : EMPTY;
            }),
            takeUntil(this.destroyed),
        ).subscribe(response => {
            this.authService.setToken(response.data.items);
        });
    }

    private listenMyImunifyState(): void {
        this.myImunifyService.getMyImunifyState().pipe(
            takeUntil(this.destroyed),
        ).subscribe(myImunifyState => {
            this.myImunifyState = myImunifyState;
            this.cdr.markForCheck();
        });
    }

    private checkLowResourceMode(): void {
        this.config.changes
            .pipe(takeUntil(this.destroyed))
            .subscribe(config => {
                if (!config) return;

                const isMinimalRuleSet = config.MOD_SEC?.ruleset === RuleSet.MINIMAL;
                const lowResourcesMode = (!config.WEBSHIELD?.enable || this.panel.isNoPanel) && isMinimalRuleSet;

                if (this.appState.lowResourcesMode$.getValue() !== lowResourcesMode) {
                    this.appState.lowResourcesMode$.next(lowResourcesMode);
                }
            });
    }
}
