import { PANEL_DEFAULT_LANGUAGE, TranslateService } from 'app/utils/translate/translate.service';
import { AuthState } from 'app/services/auth-state';
import { AuthService } from 'app/services/auth';
import { Component, ElementRef, ViewChild } from '@angular/core';
import { Panel } from 'app/utils/panel';
import { MatMenu } from '@angular/material/menu';


@Component({
    templateUrl: './menu-profile.component.html',
    styleUrls: ['./menu-profile.component.scss'],
    selector: 'i360-menu-profile',
})
export class MenuProfileComponent {

    panelLang = PANEL_DEFAULT_LANGUAGE;

    @ViewChild('langsTrigger', { read: ElementRef }) langsTrigger: ElementRef;
    @ViewChild('langsMenu') langsMenu: MatMenu;

    constructor(
        public translate: TranslateService,
        public authState: AuthState,
        public authService: AuthService,
        public panel: Panel,
    ) {}

    onLangsMenuOpen(): void {
        if (!this.langsTrigger || !this.langsMenu) return;
        const rect = this.langsTrigger.nativeElement.getBoundingClientRect();
        const gapToWindowEdge = window.innerWidth - rect.right;
        const position = gapToWindowEdge > rect.width ? 'before' : 'after';
        this.langsMenu.xPosition = position;
    }
}
