import {
    AgentResponse,
    DataFrom,
    ExtendedRequestParams,
    ListResponseData,
    NullAgentResponse,
} from './misc';
import { cutOrderByParam } from './emails-settings';
import { requestCommandIE, requestMethod } from './emails';

export enum EmailActivityColumnWidth {
    ZERO = 40,
    FIRST = 400,
    SECOND = 250,
    THIRD = 250,
    FOURTH = 250,
    FIFTH = 250
}

export type ActivityItems = {
    id: string;
    parentName?: string;
    name: string;
    messages: number;
    quarantined: number;
    limit: number;
    whitelisted: boolean;
    canExpand?: boolean;
    exclusion: boolean;
    rateLimited: boolean;
    accountNAme?: string;
    type?: ActivityType;

}

export type EmailActivityAccountDomainEmail = {
    sender?: string;
} & ActivityItems;

export type EmailActivityAccountDomainScript = ActivityItems;

export type EmailActivityAccountDomain = {
    sender_emails: EmailActivityAccountDomainEmail[];
} & ActivityItems;

export type EmailActivityAccount = {
    domains: EmailActivityAccountDomain[];
    scripts: EmailActivityAccountDomainScript[];
}& ActivityItems;

export class EmailActivityAccountItem {
    id: string;
    name: string;
    messages: number;
    quarantined: number;
    limit: number;
    type: ActivityType;
    whitelisted: boolean;
    rateLimited: boolean;
    exclusion: boolean;
    domains: EmailActivityAccountDomain[];
    canExpand = true;
    scripts: EmailActivityAccountDomainScript[];

    constructor(item: EmailActivityAccount) {
        this.id = item.id;
        this.name = item.name;
        this.messages = item.messages;
        this.quarantined = item.quarantined;
        this.limit = item.limit;
        this.whitelisted = item.whitelisted;
        this.exclusion = item.exclusion;
        this.rateLimited = item.rateLimited;
        this.setDomainsData(item.domains || []);
        this.setScriptData(item.scripts || []);
        this.type = ActivityType.account;
    }

    setScriptData(scripts: EmailActivityAccountDomainScript[]) {
        this.scripts = scripts.map((el) => {
                el.type =  ActivityType.script;
                el.parentName =  this.name;
                return el;
            })
    }

    setDomainsData(domains: EmailActivityAccountDomain[]) {
        this.domains = domains.map((el) => {
                el.type =  ActivityType.domain;
                el.parentName =  this.name;
                el.canExpand = true;
                if (el.sender_emails) {
                    el.sender_emails = el.sender_emails.map((el) => {
                        el.type = ActivityType.email;
                        el.parentName =  this.name;
                        return el;
                    });
                }
                return el;
            });
    }
}

export enum ActivityType {
     account = 'account',
     domain = 'domain',
     email = 'sender_email',
     script = 'script',
}

export class EmailActivityDomainApi {
    static list = (params) => <ExtendedRequestParams<DataFrom<EmailActivityDomainResponseData>>>{
        command: requestCommandIE,
        method: ['so', 'stats'],
        params: {
            ...cutOrderByParam(params),
            request_method: requestMethod.get,
        },
    }
    static updateActivity = (
        {limit, itemId, itemType, whitelisted, updateType, name}: {
            whitelisted?: boolean,
            limit?: number | string,
            itemType: ActivityType,
            itemId: number | string,
            name?: string,
            updateType: 'limit' | 'whitelist'
        }) => <ExtendedRequestParams<DataFrom<NullAgentResponse>>> {
        command: requestCommandIE,
        method: ['so', itemId.toString(), itemType, updateType],
        params: {
            ...((whitelisted !== undefined)? {whitelisted} : {}),
            ...((limit !== undefined)? {limit} : {}),
            ...((name)? {name} : {}),
            request_method: requestMethod.put,
        },
    }
}

export type EmailActivityDomainResponseData = AgentResponse<ListResponseData<EmailActivityAccount>>;
