import { Injectable } from '@angular/core';
import { XHR } from 'app/utils/xhr/xhr';
import { AuthCloudAPI } from '@imunify360-api/auth-cloud';
import { Observable, of, Subject, catchError, take, finalize } from 'rxjs';
import { AuthState } from 'app/services/auth-state';

@Injectable({ providedIn: 'root' })
export class AuthCloudService {
    constructor(
        private xhr: XHR,
        private authState: AuthState,
    ) {}

    getJwtToken(): Observable<string | undefined> {
        if (this.authState.jwtToken) {
            return of(this.authState.jwtToken);
        }

        if (this.authState.jwtTokenRequest$) {
            return this.authState.jwtTokenRequest$;
        }

        const tokenRequest$ = new Subject<string | undefined>();
        this.authState.jwtTokenRequest$ = tokenRequest$;

        this.xhr.rx(AuthCloudAPI.getJwtToken, false, false)()
            .pipe(
                take(1),
                catchError(() => of(undefined)),
                finalize(() => {
                    this.authState.jwtTokenRequest$ = null;
                })
            ).subscribe(result => {
                this.authState.jwtToken = result?.data?.items;
                tokenRequest$.next(this.authState.jwtToken);
        });

        return tokenRequest$.asObservable();
    }
}
