import { Injectable } from '@angular/core';
import { combineLatest, switchMap, Observable, map, of, noop, firstValueFrom } from 'rxjs';
import { LicenseType, Package } from '@imunify360-api/license';
import { SettingsService } from 'app/services/settings';
import { NotificationsService } from 'app/services/notifications';
import { LicenseState } from 'app/services/license-state';
import { LicenseService } from 'app/services/license';
import { InstallationBackendService } from 'app/components/installation/installation-backend.service';
import { AgentStatus } from '@imunify360-api/misc';
import { AppState } from 'app/core/app.service';
import { ModalService } from 'app/utils/modals/modal.service';
import { DowngradeDialogComponent, DowngradeDialogResult } from './downgrade-dialog.component';

@Injectable()
export class NavRootService {
    constructor(
        private appState: AppState,
        private licenseState: LicenseState,
        private modalService: ModalService,
        private licenseService: LicenseService,
        private settingsService: SettingsService,
        private notifications: NotificationsService,
        private installationBackendService: InstallationBackendService,
        ) {
    }

    checkInstallationStatusAndLicense(): Observable<void> {
        return this.checkInstallationStatus()
            .pipe(switchMap(() => {
                if (this.appState.imunifyStatus.value === AgentStatus.OK) {
                    return this.checkAndRetrieveThePleskLicense();
                }

                return of(undefined);
            }));
    }

    private checkInstallationStatus(): Observable<void> {
        // If we are in the installation process - interceptor should redirect to the installation page
        return this.installationBackendService.status({ offset: 0, limit: 1 }, false, false)
            .pipe(map(noop));
    }

    // Retrieve the license if the license type in plesk settings does not match the license type in the agent response
    private checkAndRetrieveThePleskLicense(): Observable<void> {
        return combineLatest([this.licenseState.license, this.settingsService.packageVersions]).pipe(
            switchMap(([license, versions]) => {
                const packages = versions?.packages || '';

                if (typeof i360PleskSettings !== 'undefined' && i360PleskSettings) {
                    if (license?.license_type && i360PleskSettings.licenseType) {
                        const fromMarketPlace = i360PleskSettings.marketplace;
                        const licenseTypeFromPlesk = fromMarketPlace
                            ? i360PleskSettings.licenseType : '';
                        const licenseTypeFromAgent = license.license_type;
                        const isInstalledImunify360License = licenseTypeFromAgent === LicenseType.imunify360
                            && i360PleskSettings.licenseType === LicenseType.imunify360;
                        const isImunify360Installed = packages.includes('imunify360-firewall');

                        if (fromMarketPlace && (licenseTypeFromPlesk !== licenseTypeFromAgent)) {
                            return this.licenseService.registerViaPanel().pipe(map(() => {}));
                        }
                        if (isInstalledImunify360License && !isImunify360Installed) {
                            return this.installationBackendService.start()
                                .pipe(switchMap(() => this.checkInstallationStatus()));
                        }
                    }
                }

                if (packages.includes('imunify360-firewall') && IMUNIFY_PACKAGE === Package.imunifyAV) {
                    this.showDowngradeDialog();
                }

                return of(undefined);
            })
        );
    }

    async showDowngradeDialog() {
        const result = await this.modalService.open<DowngradeDialogResult, void>(
            DowngradeDialogComponent,
            {
                panelClass: ['i360-confirm-dialog-panel'],
                data: undefined,
                autoFocus: false
            }
        );
        if (result && result.action === 'downgrade') {
            await this.startDowngrade();
        }
    }

    async startDowngrade(): Promise<void> {
        this.notifications.success('license.licenseDowngraded');
        await firstValueFrom(this.licenseService.downgradePlugin(), { defaultValue: undefined });
    }
}
