import { DataFrom, RequestParams, AgentResponse, ListResponseData } from './misc';
import { ICountry } from './lists';
import { RulePlugin } from './blocked-rules';
import { getSeverityIconClass } from './incidents';
import { makeCveLink } from './wordpress-utils';


interface IWordpressIncidentsParams {
    offset?: number;
    limit?: number;
    order_by?: string[];
    since?: number;
    to?: number;
    by_domain?: string;
    search?: string,
    by_abuser_ip?: string;
    by_country_code?: string;
}

interface IWordpressIncident {
    abuser: string | null;
    country: Partial<ICountry> | null;
    description: string;
    id: number;
    name: string;
    times?: number;
    rule: string;
    severity: number | null;
    timestamp: number;
    plugin: RulePlugin;
    domain: string | null;
    extra_info?: IWordpressExtraInfo;
}

interface IWordpressExtraInfo {
    // WordPress plugin-populated fields
    cve?: string;
    mode?: string;
    target?: string;
    slug?: string;
    version?: string;
    user_logged_in?: string | boolean | null;
    username?: string;
    user_id?: number | string | null;
    site_path?: string;
    // HTTP request details
    request_method?: string;
    script_filename?: string;
    php_self?: string;
    path_info?: string;
    request_uri?: string;
    query_string?: string;
    http_x_forwarded_for?: string;
    http_user_agent?: string;
    http_referer?: string;
    // Request data
    files?: string;
    get_names?: string;
    post_names?: string;
    raw_data?: string;
}

type WordpressIncidentsListAgentResponse = AgentResponse<ListResponseData<IWordpressIncident>>;

export class WordpressIncidentsApi {
    static listIncidents = (params: IWordpressIncidentsParams) =>
        new RequestParams<DataFrom<WordpressIncidentsListAgentResponse>>
        (['wordpress-plugin', 'list-incidents'], params)
}

export class WordpressIncident {
    id: number;
    name: string;
    description: string;
    plugin: RulePlugin;
    times: number;
    rule: string;
    severity: number | null;
    severityIconClass: string;
    cveLink: string | null;
    country: Partial<ICountry>;
    timestamp: any;
    canExpand = true;
    domain: string | null;
    abuser: string | null;

    constructor(data: IWordpressIncident) {
        this.country = data.country || {code: ''};
        this.abuser = data.abuser;
        this.description = data.description;
        this.id = data.id;
        this.name = data.name;
        this.times = data.times || 1;
        this.rule = data.rule;
        this.plugin = data.plugin;
        this.severity = data.severity;
        this.timestamp = data.timestamp;
        this.cveLink = makeCveLink(data.rule);
        this.severityIconClass = getSeverityIconClass(this.plugin, this.severity);
        this.domain = data.domain;
    }
}
